"""Corpus verdict comparison: fork oracle vs stock oracle, live, per case.

Each corpus case (must-accept parents and recorded mutants) is submitted to
both daemons (label_oracle.OracleConn per endpoint) with do_not_relay; the
(label, class) pairs are compared:
  - fork vs stock live verdicts must agree;
  - stock live must reproduce the recorded label (VM-state sanity);
  - fork live vs recorded label (the release comparison of record).
Outputs <outdir>/mismatches.json (empty list = clean), progress.json, and a
summary. Resume-safe by case id.

Both RPC endpoints and the credential file are REQUIRED options; there are
no defaults. The credential file is a plain text file of "key: value" lines
with "user" and "password" keys (see label_oracle.py).

Corpus data is read relative to this script's directory:
  corpus-h<mode>-mut/, h<mode>-accept-parents.jsonl, h<mode>-labels.json
  (mode parm-mut uses corpus-parm-mut/)

Usage:
  fork_compare.py <1|2> <outdir> --stock-endpoint HOST:PORT --fork-endpoint HOST:PORT --credential-file PATH
  fork_compare.py parm-mut <outdir> --stock-endpoint HOST:PORT --fork-endpoint HOST:PORT --credential-file PATH
"""
import argparse
import json, os, sys, time

import label_oracle as lo


class Arm:
    def __init__(self, host, port):
        self.c = lo.OracleConn(host, port)
        self.port = port

    def label_tx(self, tx_hex):
        return lo.label_tx_conn(self.c, tx_hex)

    def flush(self):
        try:
            self.c.rpc("flush_txpool", {"txids": []})
        except Exception:
            pass


def run_case(stock, fork, cid, tx_hex, rec_label):
    for attempt in range(4):
        try:
            s = stock.label_tx(tx_hex)
            f = fork.label_tx(tx_hex)
            break
        except (RuntimeError, OSError):
            if attempt == 3:
                raise
            time.sleep(1.5)
    bad = []
    if s != f:
        bad.append(f"fork!=stock: fork={f} stock={s}")
    if rec_label is not None:
        if s[0] != rec_label:
            bad.append(f"stock-live!=recorded: {s[0]} vs {rec_label}")
        if f[0] != rec_label:
            bad.append(f"fork-live!=recorded: {f[0]} vs {rec_label}")
    if "accept" in (s[0], f[0]):
        stock.flush()
        fork.flush()
    return {"id": cid, "fork": f, "stock": s, "recorded": rec_label, "problems": bad}


def main():
    ap = argparse.ArgumentParser(
        description="Live fork-vs-stock corpus verdict comparison.")
    ap.add_argument("mode", help="corpus mode (1 or 2), or parm-mut")
    ap.add_argument("outdir", help="output directory for progress/mismatches")
    ap.add_argument("--stock-endpoint", required=True, metavar="HOST:PORT",
                    help="stock-daemon RPC endpoint (required, no default)")
    ap.add_argument("--fork-endpoint", required=True, metavar="HOST:PORT",
                    help="fork-daemon RPC endpoint (required, no default)")
    ap.add_argument("--credential-file", required=True, metavar="PATH",
                    help='text file of "key: value" lines with "user" and '
                         '"password" keys (required, no default)')
    ap.add_argument("--corpus-dir", required=True, metavar="PATH",
                    help="corpus directory holding the case sets and labels: "
                         "corpus-h{1,2}-mut/, corpus-parm-mut/, "
                         "h{1,2}-accept-parents.jsonl, h{1,2}-labels.json "
                         "(required, no default)")
    a = ap.parse_args()
    if a.mode != "parm-mut" and a.mode not in ("1", "2"):
        ap.error("mode must be 1, 2, or parm-mut")

    lo.CRED = a.credential_file
    shost, sport = lo.parse_endpoint(a.stock_endpoint)
    fhost, fport = lo.parse_endpoint(a.fork_endpoint)
    stock = Arm(shost, sport)
    fork = Arm(fhost, fport)

    if a.mode == "parm-mut":
        parm_mut(a.outdir, stock, fork, a.corpus_dir)
        return
    h = a.mode
    outdir = a.outdir
    os.makedirs(outdir, exist_ok=True)
    base = a.corpus_dir
    mut_dir = os.path.join(base, f"corpus-h{h}-mut")
    parents_jsonl = os.path.join(base, f"h{h}-accept-parents.jsonl")
    recorded = {r["tx_hash"]: r for r in json.load(open(os.path.join(base, f"h{h}-labels.json")))}

    progress_path = os.path.join(outdir, "progress.json")
    progress = json.load(open(progress_path)) if os.path.exists(progress_path) else {}
    mism_path = os.path.join(outdir, "mismatches.json")
    mismatches = json.load(open(mism_path)) if os.path.exists(mism_path) else []

    def save():
        json.dump(progress, open(progress_path, "w"))
        json.dump(mismatches, open(mism_path, "w"))

    n_acc = 0
    for line in open(parents_jsonl):
        rec = json.loads(line)
        r = recorded.get(rec["tx_hash"])
        if not r or r["label"] != "accept":
            continue
        cid = "acc-" + rec["tx_hash"][:12]
        if cid in progress:
            continue
        res = run_case(stock, fork, cid, rec["as_hex"], "accept")
        progress[cid] = res
        if res["problems"]:
            mismatches.append(res)
            print("MISMATCH", cid, res["problems"], flush=True)
        n_acc += 1
        if n_acc % 50 == 0:
            print(f"accepts done {n_acc}", flush=True)
            save()

    n_mut = 0
    for case in json.load(open(os.path.join(mut_dir, "labels.json"))):
        cid = case["id"]
        if cid in progress:
            continue
        tx_hex = open(os.path.join(mut_dir, cid + ".hex")).read().strip()
        res = run_case(stock, fork, cid, tx_hex, case["label"])
        progress[cid] = res
        if res["problems"]:
            mismatches.append(res)
            print("MISMATCH", cid, res["problems"], flush=True)
        n_mut += 1
        if n_mut % 100 == 0:
            print(f"mutants done {n_mut}", flush=True)
            save()

    save()
    print(f"DONE h{h}: {len(progress)} cases, {len(mismatches)} mismatches", flush=True)


def parm_mut(outdir, stock, fork, corpus_dir):
    """Sweep corpus-parm-mut/*.hex (mutant_gen.py output) with rec_label=None:
    no recorded checks exist for these new shapes — compare ONLY fork-live vs
    stock-live (mismatch when fork != stock)."""
    os.makedirs(outdir, exist_ok=True)
    base = corpus_dir
    mut_dir = os.path.join(base, "corpus-parm-mut")
    cases = json.load(open(os.path.join(mut_dir, "labels.json")))

    progress_path = os.path.join(outdir, "progress.json")
    progress = json.load(open(progress_path)) if os.path.exists(progress_path) else {}
    mism_path = os.path.join(outdir, "mismatches.json")
    mismatches = json.load(open(mism_path)) if os.path.exists(mism_path) else []

    def save():
        json.dump(progress, open(progress_path, "w"))
        json.dump(mismatches, open(mism_path, "w"))

    n = 0
    for case in cases:
        cid = case["id"]
        if cid in progress:
            continue
        tx_hex = open(os.path.join(mut_dir, cid + ".hex")).read().strip()
        res = run_case(stock, fork, cid, tx_hex, None)
        progress[cid] = res
        if res["problems"]:
            mismatches.append(res)
            print("MISMATCH", cid, res["problems"], flush=True)
        n += 1
        if n % 100 == 0:
            print(f"parm-mut done {n}", flush=True)
            save()

    save()
    print(f"DONE parm-mut: {len(progress)} cases, {len(mismatches)} mismatches",
          flush=True)


if __name__ == "__main__":
    main()
